class Solution {
    public int[] maxSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        int[] q = new int[n];
        int head = 0, tail = 0, idx = 0;
        int[] res = new int[n - k + 1];
        for (int i = 0; i < n; i++) {
            while (tail > head && nums[q[tail - 1]] <= nums[i]) tail--;
            q[tail++] = i;
            if (q[head] <= i - k) head++;
            if (i >= k - 1) res[idx++] = nums[q[head]];
        }
        return res;
    }
}

