import java.util.*;

class Solution {
    public String minWindow(String s, String t) {
        Map<Character, Integer> need = new HashMap<>();
        for (char ch : t.toCharArray()) need.merge(ch, 1, Integer::sum);
        Map<Character, Integer> win = new HashMap<>();
        int have = 0, want = need.size();
        int left = 0, ansL = 0, ansR = -1, best = s.length() + 1;
        for (int right = 0; right < s.length(); right++) {
            char ch = s.charAt(right);
            if (need.containsKey(ch)) {
                win.merge(ch, 1, Integer::sum);
                if (win.get(ch).intValue() == need.get(ch).intValue()) have++;
            }
            while (have == want) {
                if (right - left + 1 < best) {
                    best = right - left + 1;
                    ansL = left;
                    ansR = right;
                }
                char c = s.charAt(left);
                if (need.containsKey(c)) {
                    win.merge(c, -1, Integer::sum);
                    if (win.get(c) < need.get(c)) have--;
                }
                left++;
            }
        }
        return best <= s.length() ? s.substring(ansL, ansR + 1) : "";
    }
}

